PREFIX moose: <https://trivyn.io/ontologies/moose#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?subjectLabel ?p ?objectLabel WHERE {
  ?subject rdfs:label "RN legacy same-PR platforms" .
  ?subject ?p ?object .
  OPTIONAL { ?object rdfs:label ?objectLabel }
  OPTIONAL { ?subject rdfs:label ?subjectLabel }
  FILTER(?p != rdfs:label)
}
ORDER BY ?p ?objectLabel

