PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX moose: <https://trivyn.io/ontologies/moose#>
SELECT ?decisionLabel ?reqLabel WHERE {
  VALUES ?decisionLabelWanted { "Native bridge phased rollout" "RN legacy bridge resolver" }
  ?decision rdfs:label ?decisionLabelWanted .
  ?decision rdfs:label ?decisionLabel .
  OPTIONAL {
    ?decision moose:isMotivatedBy ?req .
    ?req rdfs:label ?reqLabel .
  }
}
ORDER BY ?decisionLabel ?reqLabel

